#!/usr/bin/env bash
# Chapitre « Le référencement » + correctif : les pages éditoriales non publiées (« en construction ») ne sont plus indexables ;
# commentaires corrigés (robots, sitemap, évènement) ; fin du « Droit à l'image » rattachée à l'interface transverse.
# Prérequis : apply-droit-image-backend.sh.
# Usage (racine du repo) : bash apply-docs-referencement.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/interface/referencement.mdx" 2>/dev/null | grep -qF "title: \"Le référencement\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "export async function confirmMemberConsent" "packages/backend/src/modules/imageConsent/imageConsentOnline.service.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-droit-image-backend.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/index.mdx" "apps/web/content/docs/dev/legal/droit-a-l-image.mdx" "apps/web/src/app/(public)/about/page.tsx" "apps/web/src/app/(public)/contacts/page.tsx" "apps/web/src/app/(public)/events/[slug]/page.tsx" "apps/web/src/app/(public)/page.tsx" "apps/web/src/app/robots.ts" "apps/web/src/app/sitemap.ts" "apps/web/src/features/editorial/editorialGate.tsx")
CREATED=("apps/web/content/docs/dev/interface/referencement.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Le référencement\"" "apps/web/content/docs/dev/interface/referencement.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/interface"
base64 -d > "apps/web/content/docs/dev/interface/referencement.mdx" <<'B64'
